label><select name="utilizer_id"><option value="">— Выберите —</option><?php foreach($utilizers as$i):?><option value="<?=(int)$i['id']?>"><?=e((string)($i['short_name']?:$i['full_name']))?></option><?php endforeach;?></select></div></div><div class="notice info" style="margin-top:12px">Описание, даты, business ID и полный состав заявок берутся только из старой БД и в форме не редактируются.</div></div><div class="modal-foot is-spaced"><div></div><div class="modal-foot-actions"><button class="btn btn-ghost" type="button" onclick="closeModal('waste-trip-materialize-modal')">Отмена</button><button class="btn btn-primary" type="submit">Материализовать</button></div></div></form></div></div>
<script>(function(){var form=document.getElementById('waste-materialize-form');function sync(){var d=form.querySelector('[data-waste-destination]'),f=form.querySelector('[data-waste-utilizer-field]'),u=f.querySelector('select');f.style.display=d.value==='utilizer'?'block':'none';u.required=d.value==='utilizer';}sync();form.querySelector('[data-waste-destination]').addEventListener('change',sync);document.querySelectorAll('[data-materialize-legacy]').forEach(function(btn){btn.addEventListener('click',function(){var id=btn.dataset.materializeLegacy;document.getElementById('waste-materialize-title').textContent='Материализовать legacy-рейс #'+id;form.action='<?=app_url('/company/trips/departures/legacy')?>/'+encodeURIComponent(id)+'/materialize';openModal('waste-trip-materialize-modal');});});})();</script>
